-- Prix 1xBet de la dernière cote d'avant-match, par (match, marché, issue),
-- triplet 1X2 déplié, hors score exact (traité à part : marge de la grille
-- par match). Lecture seule. À lancer avec psql dans le dossier de sortie.
\copy (WITH last AS (SELECT DISTINCT ON (o."fixtureId", o.market, o.pick) o."fixtureId", o.market::text AS market, o.pick, o.odds, o."homeOdds", o."drawOdds", o."awayOdds" FROM odds_snapshot o JOIN fixture f ON f.id = o."fixtureId" WHERE o.bookmaker = '1xBet' AND o.line IS NULL AND o."snapshotAt" <= f."scheduledAt" AND o.market::text NOT IN ('CORRECT_SCORE') ORDER BY o."fixtureId", o.market, o.pick, o."snapshotAt" DESC) SELECT "fixtureId", market, pick, odds FROM last WHERE market <> 'ONE_X_TWO' UNION ALL SELECT "fixtureId", 'ONE_X_TWO', x.pick, x.odds FROM last CROSS JOIN LATERAL (VALUES ('HOME', "homeOdds"), ('DRAW', "drawOdds"), ('AWAY', "awayOdds")) AS x(pick, odds) WHERE market = 'ONE_X_TWO' AND x.odds IS NOT NULL) TO 'operator_prices.csv' CSV HEADER
-- Grille de score exact 1xBet par match : nombre de scores et marge.
\copy (WITH last AS (SELECT DISTINCT ON (o."fixtureId", o.pick) o."fixtureId", o.pick, o.odds FROM odds_snapshot o JOIN fixture f ON f.id = o."fixtureId" WHERE o.bookmaker = '1xBet' AND o.market::text = 'CORRECT_SCORE' AND o."snapshotAt" <= f."scheduledAt" ORDER BY o."fixtureId", o.pick, o."snapshotAt" DESC) SELECT "fixtureId", pick, odds FROM last) TO 'operator_scores.csv' CSV HEADER
-- Championnat de chaque match, pour la marge par championnat.
\copy (SELECT f.id AS "fixtureId", c.code AS competition, (f."scheduledAt" AT TIME ZONE 'UTC')::date AS day FROM fixture f JOIN season s ON s.id = f."seasonId" JOIN competition c ON c.id = s."competitionId" WHERE f."scheduledAt" >= DATE '2026-09-13') TO 'fixtures.csv' CSV HEADER
